/** `# Heading` lines start a section; blank lines split body paragraphs. */
export function parseSections(text: string): DepthDiveSection[] {
  const blocks = (text.trim() ? text : DEFAULT_TEXT)
    .split(/\n\s*\n/)
    .map((b) => b.trim())
    .filter(Boolean);
  const sections: DepthDiveSection[] = [];
  for (const block of blocks) {
    if (block.startsWith('#')) {
      sections.push({ heading: block.replace(/^#+\s*/, ''), body: [] });
    } else if (sections.length === 0) {
      sections.push({ heading: '', body: [block] });
    } else {
      sections[sections.length - 1]!.body.push(block);
    }
  }
  return sections;
}

/**
 * Render one section to a canvas texture. Channel-packed for the shader:
 * body text in the RED channel, heading in the GREEN channel, so the
 * material colorizes them independently while sampling one texture.
 */
export function renderSection(
  section: DepthDiveSection,
  config: DepthDiveConfig,
): HTMLCanvasElement {
  const scale = LAYOUT_W / DESIGN_W;
  const bodyPx = config.fontSize * scale;
  const headPx = config.headingSize * scale;
  const lineH = bodyPx * config.lineHeight;
  const maxW = LAYOUT_W - LAYOUT_W * config.sideMargin * 2;

  const canvas = document.createElement('canvas');
  canvas.width = LAYOUT_W;
  canvas.height = 256;
  const ctx = canvas.getContext('2d')!;

  const setBodyFont = () => {
    ctx.font = `${config.fontWeight} ${bodyPx}px ${config.fontFamily}, sans-serif`;
    if ('letterSpacing' in ctx) {
      ctx.letterSpacing = `${config.letterSpacing * bodyPx}px`;
    }
  };
  const setHeadingFont = () => {
    ctx.font = `500 ${headPx}px ${config.fontFamily}, sans-serif`;
    if ('letterSpacing' in ctx) {
      ctx.letterSpacing = `${0.32 * headPx}px`;
    }
  };

  setBodyFont();
  const spaceW = ctx.measureText(' ').width;

  interface Line {
    words: string[];
    widths: number[];
    sum: number;
  }
  const lines: Line[] = [];
  const paragraphEnd: boolean[] = [];

  for (const para of section.body) {
    const words = (config.uppercase ? para.toUpperCase() : para).split(/\s+/);
    const firstLine = lines.length;
    let cur: string[] = [];
    let widths: number[] = [];
    let sum = 0;
    const flush = () => {
      if (cur.length === 0) return;
      lines.push({ words: cur, widths, sum });
      paragraphEnd.push(false);
      cur = [];
      widths = [];
      sum = 0;
    };
    for (const word of words) {
      const w = ctx.measureText(word).width;
      if (cur.length > 0 && sum + w + spaceW * cur.length > maxW) flush();
      cur.push(word);
      widths.push(w);
      sum += w;
    }
    flush();
    // widow rescue: pull a word down so no line ends with a lone word
    const last = lines.length - 1;
    if (last > firstLine) {
      const lastLine = lines[last]!;
      const prevLine = lines[last - 1]!;
      const prevLastW = prevLine.widths[prevLine.widths.length - 1]!;
      if (
        lastLine.words.length === 1 &&
        prevLine.words.length >= 3 &&
        prevLastW + spaceW + lastLine.sum <= maxW
      ) {
        const moved = prevLine.words.pop()!;
        prevLine.widths.pop();
        prevLine.sum -= prevLastW;
        lastLine.words.unshift(moved);
        lastLine.widths.unshift(prevLastW);
        lastLine.sum += prevLastW;
      }
    }
    if (lines.length > 0) paragraphEnd[lines.length - 1] = true;
  }

  const paraGap = lineH * 0.55;
  const headBlock = section.heading ? headPx + bodyPx * 0.9 : 0;
  const pad = bodyPx * 0.8;
  let totalH = pad * 2 + headBlock;
  for (let i = 0; i < lines.length; i++) {
    totalH += lineH;
    if (paragraphEnd[i] && i < lines.length - 1) totalH += paraGap;
  }
  canvas.height = Math.min(MAX_H, Math.max(128, Math.ceil(totalH)));

  ctx.fillStyle = '#000000';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.textBaseline = 'alphabetic';

  let y = pad;
  if (section.heading) {
    setHeadingFont();
    const text = section.heading.toUpperCase();
    const w = ctx.measureText(text).width;
    ctx.fillStyle = '#00ff00';
    ctx.fillText(text, (LAYOUT_W - w) / 2, y + headPx * 0.8);
    y += headBlock;
  }
  setBodyFont();
  ctx.fillStyle = '#ff0000';
  y += bodyPx * 0.8;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]!;
    const w = line.sum + spaceW * (line.words.length - 1);
    ctx.fillText(line.words.join(' '), (LAYOUT_W - w) / 2, y);
    y += lineH;
    if (paragraphEnd[i]) y += paraGap;
  }
  return canvas;
}

export function hash01(n: number): number {
  const s = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return s - Math.floor(s);
}

export { default as DepthDive } from './DepthDive.vue';
export { createDepthDive } from './dive-engine';
export { DEFAULT_TEXT, parseSections } from './dive-text';
export type {
  DepthDiveProps,
  DepthDiveConfig,
  DepthDiveSection,
  DepthDiveHandle,
  DepthDiveHudRefs,
} from './types';

export interface DepthDiveProps {
  /**
   * Markdown-ish text: `# Heading` lines start a section, blank lines split
   * paragraphs. Each section becomes one plane in the dive.
   */
  text?: string;
  /** Uppercase the body text. */
  uppercase?: boolean;
  /** Canvas-rendered font stack (loaded via document.fonts when available). */
  fontFamily?: string;
  fontWeight?: number;
  fontSize?: number;
  headingSize?: number;
  lineHeight?: number;
  /** Letter spacing in em. */
  letterSpacing?: number;
  /** Horizontal margin as a fraction of the layout width. */
  sideMargin?: number;
  /** Camera field of view; velocity warps it up to `fov + warp`. */
  fov?: number;
  /** Z distance between consecutive sections. */
  layerGap?: number;
  /** Fraction of the frustum a plane fills. */
  fill?: number;
  /** Random XY scatter of planes. */
  scatter?: number;
  /** Random Z-rotation of planes, degrees. */
  tilt?: number;
  /** Camera sway following the pointer. */
  sway?: number;
  /** Extra fov degrees at max scroll velocity. */
  warp?: number;
  scrollSpeed?: number;
  /** Scroll smoothing, 0–1 (higher = snappier). */
  damping?: number;
  /** Sections per second of idle drift. */
  autoScroll?: number;
  /** Wrap sections infinitely. */
  infinite?: boolean;
  /** Fog fade range, in sections ahead. */
  fogFar?: number;
  fogNear?: number;
  /** Where the pass-through dissolve begins, in sections ahead. */
  dissolveStart?: number;
  /** Distant planes tint toward accentColor2. */
  depthTint?: number;
  /** Static chromatic aberration. */
  rgbShift?: number;
  /** Velocity-driven chromatic aberration. */
  rgbShiftVel?: number;
  rgbShiftWarmth?: number;
  /** UV wobble amount. */
  wobble?: number;
  /** Psychedelic tunnel intensity (0 = off, matching the reference default). */
  tunnel?: number;
  tunnelTwist?: number;
  tunnelSpeed?: number;
  /** 0 = two-accent palette, 1 = full rainbow. */
  psychedelia?: number;
  hueDrift?: number;
  /** Radial star streaks intensity. */
  stars?: number;
  streaks?: number;
  grain?: number;
  vignette?: number;
  scanlines?: number;
  textColor?: string;
  headingColor?: string;
  bgColor?: string;
  /** Progress-bar fill + dissolve edge glow tint. */
  accentColor?: string;
  /** Depth tint + palette second stop. */
  accentColor2?: string;
  /** Show the HUD (title, counter, hint, progress bar). */
  showHud?: boolean;
  hudTitle?: string;
  /** Device-pixel-ratio cap. */
  renderScale?: number;
  class?: string;
}

export interface DepthDiveSection {
  heading: string;
  body: string[];
}

export type DepthDiveConfig = Required<
  Omit<DepthDiveProps, 'class' | 'showHud' | 'hudTitle'>
>;

export interface DepthDiveHudRefs {
  counter: HTMLElement | null;
  hint: HTMLElement | null;
  bar: HTMLElement | null;
}

export interface DepthDiveHandle {
  sync: (config: DepthDiveConfig) => void;
  dispose: () => void;
}
